// Symptom: the login backdrop and the ops map controls sit at the wrong stack level,
// so other layers cover them. A click on a covered control fails actionability
// ("element intercepts pointer events"), so clicking is the check.

// Login: the sign-in control must be reachable, not covered by the backdrop.
await page.goto('/login');
const signIn = page.getByRole('button', { name: 'Sign in' });
await expect(signIn).toBeVisible();
await signIn.click({ timeout: 2000 });

// Ops map: zoom controls must be reachable above the map layer.
await page.goto('/ops/radar');
const zoomIn = page.getByRole('button', { name: 'Zoom in' });
await expect(zoomIn).toBeVisible();
await expect(zoomIn).toBeEnabled();
await zoomIn.click({ timeout: 2000 });
